/** Identifiers are opaque strings generated by the engine; the domain never creates them. */
export type Id = string;
/** Milliseconds since the Unix epoch. */
export type Timestamp = number;

export type LegalForm = "SASU" | "SAS" | "EURL" | "SARL" | "EI" | "micro";

/**
 * Where the company stands. Stages only move forward and are decided by `policy.ts`
 * from what actually happened (deliverables, fulfilled obligations), never by the player.
 */
export type Stage = "idea" | "research" | "creation" | "launch" | "operating";
export const STAGES: readonly Stage[] = ["idea", "research", "creation", "launch", "operating"];

export type RoleId =
  | "cofondateur"
  | "recherche"
  | "technique"
  | "juridique"
  | "prospection"
  | "redaction"
  | "video"
  | "comptable"
  | "support";

/** Who joins, and from which stage. Chosen by Margaux from the idea; a default when nobody could choose. */
export interface StaffingEntry {
  role: RoleId;
  at: Stage;
  why: string;
}

export interface Founder {
  name: string;
  email?: string;
}

export interface Company {
  id: Id;
  name: string;
  idea: string;
  founder: Founder;
  city?: string;
  legalForm?: LegalForm;
  foundedAt: Timestamp;
  stage: Stage;
  paused: boolean;
}

/** Beta(success + 1, failure + 1) posterior of how reliably an agent delivers. */
export interface Skill {
  success: number;
  failure: number;
}

export interface Agent {
  id: Id;
  name: string;
  role: RoleId;
  hiredAt: Timestamp;
  status: "idle" | "working";
  currentTaskId?: Id;
  skill: Skill;
  /** 1 = everything external waits for the cancel window; 4 = trusted. Earned, never bought. */
  autonomy: 1 | 2 | 3 | 4;
}

/**
 * - `internal`: reversible work inside the company (research, drafts). Runs at its time.
 * - `external`: touches the outside world (send, publish, pay, file). Waits for the cancel window.
 * - `founder`: the law requires the founder to act (sign, verify identity). Never run by an agent.
 */
export type TaskKind = "internal" | "external" | "founder";
export type TaskStatus = "planned" | "running" | "done" | "failed" | "cancelled";

export interface Task {
  id: Id;
  agentId: Id;
  title: string;
  /** Why the agent decided to do it, in the agent's words. Shown everywhere. */
  why: string;
  kind: TaskKind;
  status: TaskStatus;
  /** Machine tag that policies reason about, e.g. "market-study", "statuts". */
  tag?: string;
  createdAt: Timestamp;
  scheduledAt: Timestamp;
  /** For external tasks: the founder can cancel until then. */
  cancellableUntil?: Timestamp;
  startedAt?: Timestamp;
  endedAt?: Timestamp;
  progress?: string;
  deliverableId?: Id;
  parentId?: Id;
  error?: string;
  /** Who cancelled it: the founder's cancel is a decision the team respects. */
  cancelledBy?: "founder" | "team";
}

/** A sale the founder recorded (the first one opens the « operating » stage). */
export interface Sale {
  id: Id;
  at: Timestamp;
  amountCents?: number;
  note?: string;
}

export interface Source {
  title: string;
  url?: string;
  /** ISO date the source was checked (R-SOURCE). */
  checkedAt?: string;
  /** Whether the link answered when Narthex checked it after delivery; unknown before. */
  reachable?: boolean;
}

export interface Deliverable {
  id: Id;
  taskId: Id;
  agentId: Id;
  title: string;
  summary: string;
  /** Markdown. */
  body: string;
  sources: Source[];
  createdAt: Timestamp;
  /** When Narthex checked that the cited links answer. */
  linksCheckedAt?: Timestamp;
}

export type PostKind = "update" | "deliverable" | "hire" | "plan" | "legal";

/** A message in the Fil: an agent speaking in the first person about its work. */
export interface Post {
  id: Id;
  agentId: Id;
  at: Timestamp;
  kind: PostKind;
  text: string;
  taskId?: Id;
  deliverableId?: Id;
}

export type ObligationOwner = "founder" | RoleId;

export interface Obligation {
  id: Id;
  /** Code from the legal checklist in `obligations.ts`, e.g. "B5-signer-statuts". */
  code: string;
  title: string;
  why: string;
  owner: ObligationOwner;
  status: "open" | "done";
  openedAt: Timestamp;
  due?: Timestamp;
  doneAt?: Timestamp;
  legalBasis?: string;
  /** Its owner failed MAX_ATTEMPTS times: the team stops retrying and asks the founder. */
  stuck?: { at: Timestamp; error: string };
  /** The founder asked to try again: earlier failures no longer count. */
  retriedAt?: Timestamp;
}

export interface Settings {
  /** Hours the founder has to cancel an external action before it runs. */
  cancelWindowHours: number;
  maxPurchaseEur: number;
  monthlyCapEur: number;
  /** Topics the team must always run by the founder (task tags). */
  alwaysAsk: string[];
  /** How many agents may work at the same time. */
  concurrency: number;
  /** No new work starts once this many credits were spent today (1 credit = 0,01 $). */
  dailyBudgetCredits: number;
  /** A single task is stopped past this many credits. */
  taskBudgetCredits: number;
}

export const DEFAULT_SETTINGS: Settings = {
  cancelWindowHours: 24,
  maxPurchaseEur: 100,
  monthlyCapEur: 300,
  alwaysAsk: ["prix", "publicite-payante"],
  concurrency: 3,
  dailyBudgetCredits: 300,
  taskBudgetCredits: 150,
};

export interface Usage {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  credits: number;
  /** Credits per day (YYYY-MM-DD, Paris time), for the daily budget. */
  byDay: Record<string, number>;
}

/**
 * L2 memory: one thing the team learnt, from one deliverable. Bi-temporal (Zep/Graphiti):
 * a contradicted fact is not erased, it gets an `invalidAt`, so « what did we know then » stays answerable.
 */
export interface Fact {
  id: Id;
  /** One self-contained sentence, with its figure and place when it has one. */
  text: string;
  /** What it is about: a client, a competitor, a supplier, a rule, a price… */
  subject: string;
  /** 1 (detail) to 10 (changes decisions), rated at extraction. */
  importance: number;
  deliverableId: Id;
  validFrom: Timestamp;
  invalidAt?: Timestamp;
  /** Money, pay, personal data: only the co-founder, accounting and legal see it. */
  sensitive?: boolean;
}

export interface CompanyState {
  company?: Company;
  agents: Record<Id, Agent>;
  tasks: Record<Id, Task>;
  deliverables: Record<Id, Deliverable>;
  posts: Post[];
  obligations: Record<Id, Obligation>;
  settings: Settings;
  usage: Usage;
  /** Margaux's staffing plan; the default plan applies when absent. */
  staffing?: StaffingEntry[];
  /** L1 core memory: the shared company sheet every agent reads (kept short). */
  memory: string;
  /** L2 memory: facts extracted from deliverables. */
  facts: Record<Id, Fact>;
  /** Sales recorded by the founder. */
  sales?: Sale[];
  lastSeq: number;
}
